// CORRECTED FREE AI Classification Logic
const concernText = $input.first().json.body.description || '';
const subject = $input.first().json.body.subject || '';
const fullText = subject + ' ' + concernText;

// Enhanced keyword-based classification (FREE alternative)
const urgentKeywords = ['urgent', 'emergency', 'critical', 'asap', 'immediately', 'broken', 'down', 'not working', 'error', 'crash', 'hack', 'security', 'breach'];
const highKeywords = ['important', 'deadline', 'due', 'priority', 'issue', 'problem', 'help', 'support', 'grade', 'exam', 'assignment'];
const mediumKeywords = ['question', 'inquiry', 'information', 'request', 'general', 'clarification'];
const lowKeywords = ['thanks', 'thank you', 'appreciation', 'feedback', 'suggestion'];

let urgencyLevel = 'low';
let confidenceScore = 0.6;
let reasoning = 'Classified based on keyword analysis';
let department = 'general';

const textLower = fullText.toLowerCase();

// Check for urgent keywords
if (urgentKeywords.some(keyword => textLower.includes(keyword))) {
  urgencyLevel = 'critical';
  confidenceScore = 0.9;
  reasoning = 'Contains urgent keywords: ' + urgentKeywords.filter(k => textLower.includes(k)).join(', ');
} else if (highKeywords.some(keyword => textLower.includes(keyword))) {
  urgencyLevel = 'high';
  confidenceScore = 0.8;
  reasoning = 'Contains high-priority keywords: ' + highKeywords.filter(k => textLower.includes(k)).join(', ');
} else if (mediumKeywords.some(keyword => textLower.includes(keyword))) {
  urgencyLevel = 'medium';
  confidenceScore = 0.7;
  reasoning = 'Contains medium-priority keywords: ' + mediumKeywords.filter(k => textLower.includes(k)).join(', ');
} else if (lowKeywords.some(keyword => textLower.includes(keyword))) {
  urgencyLevel = 'low';
  confidenceScore = 0.6;
  reasoning = 'Contains low-priority keywords: ' + lowKeywords.filter(k => textLower.includes(k)).join(', ');
}

// Check text length (longer descriptions often indicate more complex issues)
if (fullText.length > 200) {
  if (urgencyLevel === 'low') {
    urgencyLevel = 'medium';
    confidenceScore = 0.7;
    reasoning += '; Upgraded due to detailed description';
  }
}

// Department classification based on keywords
if (textLower.includes('grade') || textLower.includes('exam') || textLower.includes('assignment') || textLower.includes('course')) {
  department = 'academic';
} else if (textLower.includes('payment') || textLower.includes('fee') || textLower.includes('tuition') || textLower.includes('financial')) {
  department = 'finance';
} else if (textLower.includes('dorm') || textLower.includes('housing') || textLower.includes('room') || textLower.includes('accommodation')) {
  department = 'housing';
} else if (textLower.includes('library') || textLower.includes('book') || textLower.includes('research') || textLower.includes('study')) {
  department = 'library';
} else if (textLower.includes('tech') || textLower.includes('computer') || textLower.includes('system') || textLower.includes('login') || textLower.includes('password')) {
  department = 'it';
}

return {
  json: {
    concern_id: $input.first().json.body.concern_id,
    urgency_level: urgencyLevel,
    confidence_score: confidenceScore,
    reasoning: reasoning,
    suggested_department: department,
    ai_model: 'enhanced-keyword-classifier',
    classified_at: new Date().toISOString(),
    original_text: fullText.substring(0, 100) + '...'
  }
};
